config.command:
set -eu
umask 077
export LC_ALL=C
base=/workspace/fieldkit
[ -d "$base" ] && [ ! -L "$base" ] || { printf 'Create the fieldkit folder in the sandbox workspace first.\n' >&2; exit 2; }
cd "$base"
need() {
  command -v "$1" >/dev/null 2>&1 || { printf 'Missing command: %s. Install the packages listed in this tool.\n' "$1" >&2; exit 127; }
}
check_file() {
  [ -f "$1" ] && [ ! -L "$1" ] || { printf 'Required regular file missing: %s\n' "$1" >&2; exit 2; }
  bytes=$(wc -c < "$1")
  [ "$bytes" -gt 0 ] && [ "$bytes" -le "$2" ] || { printf 'Input is empty or exceeds this tool size limit.\n' >&2; exit 2; }
}
need yara
check_file rules.yar 65536
check_file input.bin 8388608
matches=$(yara -w --timeout=10 ./rules.yar ./input.bin)
if [ -n "$matches" ]; then printf '%s\n' "$matches"; else printf 'No supplied rule matched.\n'; fi
